/// <summary>
/// CB521_Exciseregister
/// Report data provider class for Nature 30 and Nature 40 report combine
/// </summary>
[SRSReportParameterAttribute(classStr(METNature3040ReportContract))]
public class METNature3040ReportCombineDP extends SRSReportDataProviderBase
{
    METNature3040ReportsTmp     metNature3040ReportsTmp;
    METNature3040ReportsTable   metNature3040ReportsTable;
}

Method.Source:
/// <summary>
/// Method to get the tmp table
/// </summary>
/// <returns>METNature3040ReportsTmp</returns>
[SrsReportDataSet(tableStr(METNature3040ReportsTmp))]
public METNature3040ReportsTmp getMETNature3040ReportsTmp()
{
    select  metNature3040ReportsTmp;
    return  metNature3040ReportsTmp;
}

    /// <summary>
    /// Process method for business logic to insert tmp table
    /// </summary>
    public void processReport()
    {
        METNature3040ReportContract   contract = this.parmDataContract();

        RecordInsertList                recordInsertList = new RecordInsertList(tableNum(METNature3040ReportsTmp), false, false, false, false, false, metNature3040ReportsTmp);

        Query   query = new Query();
        QueryBuildDataSource qbds = query.addDataSource(tableNum(METNature3040ReportsTable));

        qbds.addRange(fieldNum(METNature3040ReportsTable, Nat3040ReportNumber)).value(queryValue(contract.parmNat30Number()));

        if (contract.parmSite())
        {
            qbds.addRange(fieldNum(METNature3040ReportsTable, SiteId)).value(queryValue(contract.parmSite()));
        }
        else
        {
            qbds.fields().clearFieldList();

            // GROUP BY fields
            qbds.addGroupByAndSelectionField(fieldNum(METNature3040ReportsTable, ItemId));
            qbds.addGroupByAndSelectionField(fieldNum(METNature3040ReportsTable, TariffItem));
            qbds.addGroupByAndSelectionField(fieldNum(METNature3040ReportsTable, TariffItemDescription));
            qbds.addGroupByAndSelectionField(fieldNum(METNature3040ReportsTable, OriginCountryCode));
            qbds.addGroupByAndSelectionField(fieldNum(METNature3040ReportsTable, ItemDescription));
            qbds.addGroupByAndSelectionField(fieldNum(METNature3040ReportsTable, LUnit));
            qbds.addGroupByAndSelectionField(fieldNum(METNature3040ReportsTable, LALSUnit));
            qbds.addGroupByAndSelectionField(fieldNum(METNature3040ReportsTable, Nat3040ReportNumber));
            qbds.addGroupByAndSelectionField(fieldNum(METNature3040ReportsTable, PreferenceScheme));
            qbds.addGroupByAndSelectionField(fieldNum(METNature3040ReportsTable, PreferenceRule));
            qbds.addGroupByAndSelectionField(fieldNum(METNature3040ReportsTable, TariffRate));

            // Aggregates
            qbds.addSelectionField(fieldNum(METNature3040ReportsTable, CasesSold), SelectionField::Sum);
            qbds.addSelectionField(fieldNum(METNature3040ReportsTable, InvoiceAlcohol), SelectionField::Avg);
            qbds.addSelectionField(fieldNum(METNature3040ReportsTable, LALSQuantity), SelectionField::Sum);
            qbds.addSelectionField(fieldNum(METNature3040ReportsTable, DutyLAL), SelectionField::Avg);
            qbds.addSelectionField(fieldNum(METNature3040ReportsTable, CustomsValue), SelectionField::Sum);
            qbds.addSelectionField(fieldNum(METNature3040ReportsTable, ExciseAmount), SelectionField::Sum);
            qbds.addSelectionField(fieldNum(METNature3040ReportsTable, LQuantity), SelectionField::Sum);
            qbds.addSelectionField(fieldNum(METNature3040ReportsTable, TIUV), SelectionField::Sum);
        }

        QueryRun    queryRun = new QueryRun(query);

        while (queryRun.next())
        {
            metNature3040ReportsTable = queryRun.get(tableNum(METNature3040ReportsTable));
            metNature3040ReportsTmp.clear();
            metNature3040ReportsTmp.CasesSold           = metNature3040ReportsTable.CasesSold;
            metNature3040ReportsTmp.CustomsValue        = metNature3040ReportsTable.CustomsValue;
            metNature3040ReportsTmp.DutyLAL             = metNature3040ReportsTable.DutyLAL;
            metNature3040ReportsTmp.ExciseAmount        = metNature3040ReportsTable.ExciseAmount;
            metNature3040ReportsTmp.InvoiceAlcohol      = metNature3040ReportsTable.InvoiceAlcohol;
            metNature3040ReportsTmp.ItemDescription     = metNature3040ReportsTable.ItemDescription;
            metNature3040ReportsTmp.ItemId              = metNature3040ReportsTable.ItemId;
            metNature3040ReportsTmp.LALSQuantity        = metNature3040ReportsTable.LALSQuantity;
            metNature3040ReportsTmp.LALSUnit            = metNature3040ReportsTable.LALSUnit;
            metNature3040ReportsTmp.LQuantity           = metNature3040ReportsTable.LQuantity;
            metNature3040ReportsTmp.LUnit               = metNature3040ReportsTable.LUnit;
            metNature3040ReportsTmp.OriginCountryCode   = metNature3040ReportsTable.OriginCountryCode;
            metNature3040ReportsTmp.PreferenceScheme    = metNature3040ReportsTable.PreferenceScheme;
            metNature3040ReportsTmp.TariffItem          = metNature3040ReportsTable.TariffItem;
            metNature3040ReportsTmp.TariffItemDescription = metNature3040ReportsTable.TariffItemDescription;
            metNature3040ReportsTmp.TariffRate          = metNature3040ReportsTable.TariffRate;
            metNature3040ReportsTmp.PreferenceRule      = metNature3040ReportsTable.PreferenceRule;
            metNature3040ReportsTmp.TIUV                = metNature3040ReportsTable.TIUV;
            recordInsertList.add(metNature3040ReportsTmp);
        }
        recordInsertList.insertDatabase();
    }
